def main():
    req = json.load(open(REQ, encoding="utf-8"))
    items = req["items"]
    table = {t: (a, c, r, cl, du, tm) for (t, a, c, r, cl, du, tm) in D}
    assert len(D) == 200, len(D)
    assert len(table) == 200, len(table)
    titles_req = [it["title"] for it in items]
    missing = [t for t in titles_req if t not in table]
    extra = [t for t in table if t not in set(titles_req)]
    assert not missing, missing
    assert not extra, extra
    decisions = []
    for it in items:
        a, c, r, cl, du, tm = table[it["title"]]
        assert (cl and du and tm) if a else (not cl or not du or not tm), it["title"]
        decisions.append({
            "title": it["title"],
            "approve": a,
            "confidence": c,
            "reason": r,
            "checks": {"clarity": cl, "duplication": du, "trademark": tm},
        })
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    tmp_path = OUT + ".tmp"
    with open(tmp_path, "w", encoding="utf-8", newline="\n") as f:
        json.dump(decisions, f, ensure_ascii=False, indent=1)
        f.write("\n")
    os.replace(tmp_path, OUT)
    n_app = sum(1 for d in decisions if d["approve"])
    print("items=%d approve=%d reject=%d" % (len(decisions), n_app, len(decisions) - n_app))
    print("out=", OUT)

if __name__ == "__main__":
    main()
